    required_len = 1 + (N-1)*abs(incX) if N > 0 else 0
    if len(X) < required_len:
        raise ValueError(f'X must have at least {required_len} elements for given N and incX')
    for z in X:
        if not isinstance(z, (complex, int, float)):
            raise TypeError('All elements in X must be complex or real numbers')
    flat_X = []
    for z in X:
        z_complex = complex(z)
        flat_X.append(z_complex.real)
        flat_X.append(z_complex.imag)
    array_type = ctypes.c_double * len(flat_X)
    c_X = array_type(*flat_X)
